        PipelineStageStatus(
            stage="vae_training",
            status="complete" if vae_ckpt.exists() else "pending",
            detail=str(vae_ckpt) if vae_ckpt.exists() else "No VAE checkpoint",
        )
    )

    rl_ckpt = Path("data/rl/checkpoints/policy_final.pt")
    stages.append(
        PipelineStageStatus(
